import React from "react";
import SubHeading from "../../../Components/Heading/SubHeading";
import muc from "./mercury-11591_640.png"

function Section4() {
  let obj = [
    {
      "planet": "Mercury",
      "img": muc,
      "para":
      ""
    },
  ];

  const solarSystemPlanets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune",
  ];

  return (
    <div className=" w-full h-screen ">
      <SubHeading text="Solar System Planets" />
      {
        obj.map((ele)=>{
          ele.para
          
        })
      }
      <div className=""></div>
    </div>
  );
}

export default Section4;
